import{z as i,x as s,o as A,c as d,q as r,j as B,D as e,d as t,s as n,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"真实经济周期对照","description":"","frontmatter":{"title":"真实经济周期对照","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/rbc-contrast.md","filePath":"econ/rbc-contrast.md","lastUpdated":1791413859000}'),p={name:"econ/rbc-contrast.md"};function m(c,a,u,C,f,h){const l=s("Mermaid");return A(),d("div",null,[a[2]||(a[2]=r('<h1 id="真实经济周期对照" tabindex="-1">真实经济周期对照 <a class="header-anchor" href="#真实经济周期对照" aria-label="Permalink to &quot;真实经济周期对照&quot;">​</a></h1><div class="epigraph"><p>若价格灵活、市场出清，周期也可以是对技术与偏好冲击的最优反应；货币在其中不是驱动项。</p><footer>—— Kydland and Prescott, Time to Build and Aggregate Fluctuations, Econometrica 1982；对照 Lucas 的均衡周期</footer></div><p><a href="/econ/financial-accelerator">上一课</a>（金融加速器）。让名义刚性把利率政策接到缺口。本课的对照是：把刚性拿掉，周期还剩什么。Kydland 与 Prescott（1982）把索洛的 \\(A\\) 写成随机过程，用可计算的 Ramsey 均衡去匹配产出、消费、投资、工时的二阶矩。下一课（卢卡斯批判）会问：这些矩对政策是否结构；本课先把 RBC 的主张钉住。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>新凯恩斯把 \\(\\tilde{y}\\) 读成需求不足或过度。RBC 的缺口是：同样的 \\(y\\) 波动，可以是自然产出自己在动——技术冲击改变 \\(F(K,AL)\\)，家庭沿欧拉与劳动供给最优地响应。没有未出清的商品市场，也没有未预期到的通胀菜单。问题不是「周期是否存在」，而是：有多少波动必须用粘性来解释，多少在灵活价格下已经能复制。</p><p>Lucas 更早把周期写成均衡中的信息混淆。RBC 把信息问题换成可观测的技术与跨期替代。两者都拒绝把 IS–LM 的静态乘数当结构。</p><p><span class="marginnote">术语翻译：「二阶矩」就是方差与协方差这类刻画波动大小和相互联动程度的统计量。校准的目标是让模型里产出、消费、投资、工时各自波动多大、彼此同步多强，跟数据里同名的量对得上，而不是去拟合某一次具体衰退的时间线。</span></p><p><span class="marginnote">索洛残差在此被当成外生技术冲击的代理。发展核算里 \\(A\\) 是水平残差；RBC 的 \\(A\\) 是时间上的随机趋势或平稳冲击。测量误差和要素囤积会污染残差，这是对照的边界。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>代表性家庭、完全市场、灵活价格。冲击主要是 \\(A_t\\)（也可加政府购买、偏好）。决策：消费欧拉、劳动–闲暇、资本积累。均衡配置即计划者配置（无外部性时）。校准：选参数使稳态匹配长期份额，再看模型矩与数据矩。</p>',10)),(A(),B(o,null,{default:e(()=>[n(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%8A%80%E6%9C%AF%E5%86%B2%E5%87%BB%20A%22%5D%20--%3E%20NAT%5B%22%E8%87%AA%E7%84%B6%E4%BA%A7%E5%87%BA%E6%B3%A2%E5%8A%A8%22%5D%0A%20%20EU%5B%22%E6%AC%A7%E6%8B%89%E4%B8%8E%E5%8A%B3%E5%8A%A8%E4%BE%9B%E7%BB%99%22%5D%20--%3E%20NAT%0A%20%20NK%5B%22NK%EF%BC%9A%E7%B2%98%E6%80%A7%20%E2%86%92%20%E7%BC%BA%E5%8F%A3%22%5D%20--%3E%20COMP%5B%22%E5%AF%B9%E7%85%A7%EF%BC%9A%E5%90%8C%E4%B8%80%E7%BB%84%E5%AE%8F%E8%A7%82%E7%9F%A9%22%5D%0A%20%20NAT%20--%3E%20COMP%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与 NK 的差别不在欧拉——两边都用——而在 Phillips：\\(κ\\to\\infty\\) 时 \\(\\pi\\) 不携带独立的名义需求故事，货币中性在周期频率上也近似成立。经验上货币与产出的同期相关，RBC 必须用反向因果或无关的共同因子解释，或承认需要名义刚性。",-1)),a[4]||(a[4]=E("h3",{id:"校准不是估计因果",tabindex:"-1"},[t("校准不是估计因果 "),E("a",{class:"header-anchor",href:"#校准不是估计因果","aria-label":'Permalink to "校准不是估计因果"'},"​")],-1)),a[5]||(a[5]=E("p",null,"匹配二阶矩不等于识别了冲击。把索洛残差当 \\(A\\)，等于把模型解释不了的产出都叫技术。NK 可以把同一残差拆成技术加 markup 加需求。本课的用处是对照：拒绝「没有粘性就没有周期」。",-1)),a[6]||(a[6]=E("p",null,"Kydland–Prescott 用建设时间让投资冲击变成持续产出动态。劳动供给弹性必须够大才能匹配工时矩——这是后来转向劳动市场摩擦的经验压力，不是把乘数请回来。",-1)),a[7]||(a[7]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[8]||(a[8]=E("p",null,"正技术冲击提高劳动边际产出，工资与就业、消费、投资一起升（投资往往更剧烈，因为资本要调到新的合意水平）。这是跨期替代，不是失业者被「需求创造」出来。自然率 \\(u^*\\) 仍可为正（摩擦），但周期性 \\(\\tilde{u}\\) 在纯 RBC 里主要是自愿的工时变动——这正是最受批评的一点：失业看上去不像闲暇。",-1)),(A(),B(o,null,{default:e(()=>[n(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20TS%5B%22%E6%AD%A3%E6%8A%80%E6%9C%AF%E5%86%B2%E5%87%BB%22%5D%20--%3E%20MPL%5B%22%E5%8A%B3%E5%8A%A8%E8%BE%B9%E9%99%85%E4%BA%A7%E5%87%BA%E4%B8%8A%E5%8D%87%22%5D%0A%20%20MPL%20--%3E%20WAGE%5B%22%E5%AE%9E%E9%99%85%E5%B7%A5%E8%B5%84%E4%B8%8A%E5%8D%87%22%5D%0A%20%20WAGE%20--%3E%20LAB%5B%22%E8%B7%A8%E6%9C%9F%E6%9B%BF%E4%BB%A3%EF%BC%9A%E4%BB%8A%E5%A4%A9%E5%A4%9A%E5%B9%B2%E5%87%A0%E5%B0%8F%E6%97%B6%22%5D%0A%20%20MPL%20--%3E%20INV%5B%22%E6%8A%95%E8%B5%84%E5%8A%A0%E7%A0%81%EF%BC%9A%E6%8A%8A%E8%B5%84%E6%9C%AC%E8%B0%83%E5%90%91%E6%96%B0%E7%9A%84%E5%90%88%E6%84%8F%E6%B0%B4%E5%B9%B3%22%5D%0A%20%20LAB%20--%3E%20Y%5B%22%E4%BA%A7%E5%87%BA%E4%B8%8E%E6%B6%88%E8%B4%B9%E4%B8%80%E5%90%8C%E4%B8%8A%E5%8D%87%22%5D%0A%20%20INV%20--%3E%20Y%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=r('<p><span class="marginnote">直觉类比：跨期替代像「挑天气干活」——今天工资格外高（技术好、产出值钱），就多干几小时、把收入存起来，明天机会差时少干点。数字实例：若今天的实际工资比平常高 5%，家庭愿意把工时提高几个百分点；劳动供给弹性越大，同样的工资差距换来的工时反应越猛，这也是 RBC 匹配工时矩的关键参数。</span></p><p>增长课的稳态仍在：RBC 是稳态附近的随机扰动，不是另一套索洛。内生增长可以把 \\(A\\) 的趋势内生化，周期模型通常仍把高频冲击外生。建设时间（time to build）让投资冲击变成持续的产出动态，这是 1982 年标题里的机制，不是把乘数请回来。</p><p>若市场完整、冲击真是技术、无外部性，用需求管理去抹平 \\(y\\) 可能降低福利——波动是最优反应。一旦存在粘性或市场外失业，同样冲击的传播改变，稳定政策可以有空间。本课不裁定福利，只标前提。</p><p><span class="marginnote">HP 滤波把增长与周期切开。滤波选择会改变矩，这是方法的一部分。把滤波后的「周期」直接叫成 NK 缺口，是把两种分解混用。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>RBC 不解释滞胀里通胀与失业同升的名义面，也不给铸币税角色。工时波动过大、失业的非自愿性，是转向 NK 与劳动市场摩擦的理由。本栏仍不把周期写成限价簿上的订单流。大萧条式的持续大规模失业，除非把 \\(A\\) 写成离奇的负技术，否则纯 RBC 吃力。</p><p><span class="marginnote">常见误区：初学者容易把 RBC 读成「失业是自愿的，所以大萧条没什么好解释」。实际上 RBC 的主张是范围性的：它能复制温和的工时与产出联动，但对持续多年、规模巨大的失业，只能靠假设离奇的负技术冲击硬凑——这正是它被 NK 和劳动摩擦模型替代解释的原因。</span></p><p>后课默认：灵活价格下已有真实驱动的波动；名义刚性解释的是额外的缺口与货币非中性。下一课：无论 RBC 还是 NK，用历史简化式做政策评估都会翻车。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>灵活价格下，技术等真实冲击足以产生周期矩的一部分。</li><li>欧拉共用；差别在价格是否出清、货币是否中性到周期频率。</li><li>索洛残差当冲击有测量污染；滤波选择会改矩。</li><li>稳定政策的福利取决于摩擦是否存在。</li><li>政策评估不能靠未对规则变化做结构的回归——卢卡斯批判。</li><li>出处：Kydland and Prescott, Econometrica 1982；Lucas 的均衡周期传统。</li></ul>',10))])}const D=i(p,[["render",m]]);export{b as __pageData,D as default};
